const videoEl = document.getElementById('cam')
const glCanvas = document.getElementById('gl')

let facing = 'user'
let currentFilter = 'grandpa'
let faceLandmarker = null
let videoStream = null
let latestResult = null
let latestLandmarks = null
let trackingFound = null
// Framebuffer-clear investigation: how many upcoming loop() frames should
// still post pre/post-render diagnostics. Set by clearActiveFilter() so the
// frames right after a filter switch are the ones actually inspected,
// instead of every frame for the whole session (which would flood the
